const payload = $input.first().json;
const data = payload.data || payload;

return [{
  json: {
    subject: `🏍️ Rider Assigned to Order ${data.trackingNumber}`,
    customerNotification: {
      title: 'Rider on the Way!',
      message: `${data.riderName || 'A rider'} has accepted your order and is heading to ${data.pharmacyName || 'the pharmacy'}.`,
      recipientEmail: data.userEmail,
      recipientName: data.userName
    },
    riderNotification: {
      title: 'Order Pick-up Instructions',
      pharmacy: data.pharmacyName,
      deliveryAddress: data.deliveryAddress,
      recipientEmail: data.riderEmail,
      recipientName: data.riderName
    },
    body: `Order ${data.trackingNumber} has been assigned to rider ${data.riderName} (${data.riderEmail}).\n` +
          `Customer: ${data.userName} (${data.userEmail})\n` +
          `Pickup: ${data.pharmacyName}\n` +
          `Drop: ${data.deliveryAddress}\n\n` +
          `Assigned at: ${payload.timestamp || new Date().toISOString()}`,
    orderId: data.orderId,
    trackingNumber: data.trackingNumber,
    riderId: data.riderId
  }
}];
